'use strict';
const SeenTalk=(()=>{
 const dialog=document.createElement('dialog');dialog.id='npc-dialog';dialog.setAttribute('aria-labelledby','npc-title');dialog.innerHTML='<button class="icon-close talk-close" type="button" aria-label="Close conversation">'+seenCloseIcon+'</button><span class="talk-role"></span><div class="talk-avatar" aria-hidden="true"><span></span></div><h2 id="npc-title"></h2><p class="talk-line" role="status"></p><div class="talk-options"></div>';document.body.append(dialog);let afterClose=null,anchor=null,lastNearby=null,context=null;
 function close(){if(dialog.open)dialog.close()}
 dialog.querySelector('.talk-close').onclick=close;dialog.addEventListener('close',()=>{SeenHub.releaseNpc(anchor?.id);anchor=null;const fn=afterClose;afterClose=null;fn?.();document.querySelector(document.body.dataset.scene==='screening'?'#room-world':document.body.dataset.scene==='arcade-room'?'#arcade-world':'#world').focus({preventScroll:true})});
 function show({name,role='CINEMA HOST',line,options=[],onClose}){afterClose=onClose||null;dialog.querySelector('.talk-role').textContent=role;dialog.querySelector('h2').textContent=name;dialog.querySelector('.talk-line').textContent=line;const actions=dialog.querySelector('.talk-options');actions.replaceChildren();for(const option of options){const button=document.createElement('button');button.type='button';button.textContent=option.label;button.onclick=option.action;actions.append(button)}if(!dialog.open){dialog.showModal();document.dispatchEvent(new Event('seen-conversation-open'))}dialog.style.left=`${Math.max(10,(innerWidth-dialog.offsetWidth)/2)}px`;dialog.style.top=`${Math.max(72,(innerHeight-dialog.offsetHeight)/2)}px`;dialog.querySelector('.talk-close').focus({preventScroll:true});requestAnimationFrame(()=>context&&nearby(context))}
 function canTalk(person){return !!context&&Math.hypot(person.x-context.x,person.y-context.y)<(person.uniform?2.3:person.posture?1.45:1.25)}
 function staff(person){if(!canTalk(person))return false;if(anchor?.id!==person.id)SeenHub.releaseNpc(anchor?.id);anchor=person;SeenHub.holdNpc(person);const ticket=person.id==='lobby:npc:0',popcorn=person.id==='lobby:npc:1';if(ticket){show({name:'Mia',role:'TICKET BOOTH · NPC',line:'Welcome to SEEN. Which story shall we find you a seat for?',options:[...rooms.map(r=>({label:`SCREEN ${r.n} · ${r.name}`,action:()=>{close();walkToScreen(r)}})),{label:'Where is the arcade?',action:()=>{close();walkToGame()}}]})}else if(popcorn){show({name:'Leo',role:'POPCORN SHOP · NPC',line:'One film, one conversation, one popcorn. What can I get you?',options:[{label:'A popcorn, please',action:()=>show({name:'Leo',role:'POPCORN SHOP · NPC',line:'Yes! A fresh popcorn, on the house. Enjoy the screening.',options:[{label:'Thank you!',action:()=>{let snack=document.querySelector('#snack-receipt');if(!snack){snack=document.createElement('span');snack.id='snack-receipt';snack.textContent='POPCORN · ON THE HOUSE';document.querySelector('#lobby-scene').append(snack)}setTimeout(()=>snack.remove(),4500);close()}}]})},{label:'What do you recommend?',action:()=>show({name:'Leo',role:'POPCORN SHOP · NPC',line:'Try a screening first, then talk about the detail that stayed with you. The arcade is great for an encore.',options:[{label:'Sounds good',action:close}]})}]})}else show({name:person.npc?'A fellow film lover':person.name,role:person.npc?'CINEMA GUEST · NPC':'LIVE VISITOR',line:person.npc?'A good film is better with company. What brings you here?':'Another visitor is exploring the cinema with you.',options:person.npc?[{label:'Recommend a film',action:()=>show({name:'A fellow film lover',line:'I would start with A Seat at the Table. Family stories always stay with me.',options:[{label:'Take me to Screen 01',action:()=>{close();walkToScreen(rooms[0])}},{label:'I prefer a game',action:()=>{close();walkToGame()}}]})},{label:'I am here for the arcade',action:()=>show({name:'A fellow film lover',line:'Try EYES ONLY if you remember faces, or FILM CLUB for movie trivia.',options:[{label:'Let’s play',action:()=>{close();walkToGame()}},{label:'Maybe later',action:close}]})},{label:'See you around',action:close}]:[{label:'See you around',action:close}]})}
 async function askSeat(person,{seatId,scene,onYes}){anchor=person;SeenHub.holdNpc(person);show({name:person.npc?'A fellow film lover':person.name,role:person.npc?'SEATED GUEST · NPC':'LIVE VISITOR',line:`This is seat ${seatId}. Would you like to ask if you can take this seat?`,options:[{label:'Ask to change seats',action:async()=>{show({name:person.npc?'A fellow film lover':person.name,role:person.npc?'SEATED GUEST · NPC':'LIVE VISITOR',line:'“Would you mind changing seats?”',options:[]});let answer;if(person.npc){await new Promise(r=>setTimeout(r,650));if(!dialog.open)return;answer=person.id.split(':').at(-1)!=='1'}else{answer=await SeenHub.requestSeat(person,{seatId,scene});if(!dialog.open)return}const line=answer===true?'Yes — you can have my seat. I’ll find another spot.':answer===false?'No, I’d like to stay in this seat. Thanks for asking.':'No reply yet. They may be reading or away. Try another seat.';show({name:person.npc?'A fellow film lover':person.name,role:person.npc?'SEATED GUEST · NPC':'LIVE VISITOR',line,options:[{label:answer===true?'Take the seat':'Choose another seat',action:()=>{close();if(answer===true)onYes()}}]})}},{label:'Never mind',action:close}]})}
 function incoming(req,onYes){anchor=SeenHub.people(req.scene).find(v=>v.id===req.from)||null;let answered=false;const reply=yes=>{answered=true;SeenHub.replySeat(req,yes);close();if(yes)onYes()};show({name:req.name,role:'SEAT REQUEST · LIVE VISITOR',line:`Would you let ${req.name} take seat ${req.seatId}? If you say Yes, you’ll move to another available seat.`,options:[{label:'No · Keep my seat',action:()=>reply(false)},{label:'Yes · I can move',action:()=>reply(true)}],onClose:()=>{if(!answered)SeenHub.replySeat(req,false)}})}
 function nearby({scene,x,y,project,canvas}){context={scene,x,y,project,canvas};const persons=SeenHub.people(scene);if(anchor&&dialog.open){const current=persons.find(v=>v.id===anchor.id)||anchor,q=project(current.x+Math.cos(current.heading||0)*.015,current.y+Math.sin(current.heading||0)*.015,1.49-.12*(current.posture||0)+(current.jump||0)),r=canvas.getBoundingClientRect();const headX=r.left+q.x,headY=r.top+q.y,ceiling=Math.max(8,document.querySelector('.site-header').getBoundingClientRect().bottom+8);dialog.style.maxHeight=`${Math.max(110,headY-ceiling-16)}px`;const w=dialog.offsetWidth,h=dialog.offsetHeight,left=Math.max(10,Math.min(innerWidth-w-10,headX-w/2));dialog.style.left=`${left}px`;dialog.style.top=`${Math.max(ceiling,headY-h-16)}px`;dialog.style.setProperty('--talk-tail-left',`${Math.max(15,Math.min(w-30,headX-left-8))}px`)}if(dialog.open)return;const n=persons.find(v=>v.npc&&v.posture<.5&&Math.hypot(v.x-x,v.y-y)<(v.uniform?2.3:1.2));if(!n){lastNearby=null;return}lastNearby=n.id}

 document.addEventListener('keydown',e=>{if(dialog.open&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','KeyW','KeyA','KeyS','KeyD','Space'].includes(e.code)){e.preventDefault();e.stopImmediatePropagation()}},true);
 document.addEventListener('seen-language-change',()=>{if(context&&dialog.open)requestAnimationFrame(()=>nearby(context))});
 return{canTalk,staff,askSeat,incoming,close,nearby};
})();
